16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Period;
23	import java.time.temporal.ChronoUnit;
24	import java.util.Map;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    private OwnerDerivations() {
48	    }
49	
50	    /**
51	     * The owner's locality, i.e. the canonical region it belongs to. This is read
52	     * from the region-and-hash {@code customerCode} identity: the region is the
53	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
54	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
55	     * been assigned a customer code (for example while its create request is still
56	     * being validated) this falls back to the region derived directly from its own
57	     * fields (see {@link #region(String, String)}).
58	     *
59	     * @return the canonical region string, or {@code "UNKNOWN"}
60	     */
61	    static String locality(String customerCode, String postcode, String city) {
62	        if (customerCode != null) {
63	            int dash = customerCode.indexOf('-');
64	            if (dash >= 0) {
65	                return customerCode.substring(0, dash);
66	            }
67	        }
68	        return region(postcode, city);
69	    }
70	
71	    /**
72	     * The canonical region derived for an owner from its own fields. The postcode is
73	     * consulted first: when it is present and falls within a known region's inclusive
74	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
75	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
76	     * known range does this fall back to the fixed city-to-region table
77	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
78	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
79	     * the same region for the known cities while disambiguating cities that share a name
80	     * via their postcode.
81	     *
82	     * @return the canonical region string, or {@code "UNKNOWN"}
83	     */
84	    static String region(String postcode, String city) {
85	        String byPostcode = regionForPostcode(postcode);
86	        if (byPostcode != null) {
87	            return byPostcode;
88	        }
89	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
90	    }
91	
92	    /**
93	     * The region whose inclusive postcode range contains the given postcode, or
94	     * {@code null} when the postcode is absent, not a four-digit number, or in no
95	     * known range.
96	     */
97	    private static String regionForPostcode(String postcode) {
98	        if (postcode == null || !postcode.matches("\\d{4}")) {
99	            return null;
100	        }
101	        int value = Integer.parseInt(postcode);
102	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
103	            int[] range = entry.getValue();
104	            if (value >= range[0] && value <= range[1]) {
105	                return entry.getKey();
106	            }
107	        }
108	        return null;
109	    }
110	
111	    /**
112	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
113	     * absent postcode is always accepted, a present postcode must be exactly four
114	     * digits and, when the region has a known inclusive postcode range
115	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
116	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
117	     * four-digit postcode.
118	     *
119	     * @return {@code true} if the postcode is absent or valid for the region
120	     */
121	    static boolean postcodeMatchesRegion(String postcode, String region) {
122	        if (postcode == null) {
123	            return true;
124	        }
125	        if (!postcode.matches("\\d{4}")) {
126	            return false;
127	        }
128	        int[] range = REGION_POSTCODES.get(region);
129	        if (range == null) {
130	            return true;
131	        }
132	        int value = Integer.parseInt(postcode);
133	        return value >= range[0] && value <= range[1];
134	    }
135	
136	    /**
137	     * The owner's membership level, a number from 1 to 4. The creation-time factors
138	     * are assessed first: starting at 1, add 1 when an {@code email} is present and add
139	     * 1 when {@code namesakeCount} is 0, capped at 3. Level 4 is then reached only once
140	     * the owner's tenure exceeds 365 days, measured as the number of whole days from its
141	     * {@code registrationDate} up to {@code asOf}. Because a newly created owner has zero
142	     * tenure, it never exceeds level 3 at creation.
143	     *
144	     * @return the membership level, from 1 to 4
145	     */
146	    static int membershipLevel(String email, Integer namesakeCount, LocalDate registrationDate,
147	            LocalDate asOf) {
148	        int level = 1;
149	        if (hasEmail(email)) {
150	            level++;
151	        }
152	        if (namesakeCount != null && namesakeCount == 0) {
153	            level++;
154	        }
155	        level = Math.min(level, 3);
156	        if (tenureExceedsYear(registrationDate, asOf)) {
157	            level++;
158	        }
159	        return level;
160	    }
161	
162	    /**
163	     * Whether the owner's tenure exceeds a year, i.e. more than 365 whole days have passed
164	     * from its {@code registrationDate} up to {@code asOf}. This is the single tenure test
165	     * the tenure-driven membership derivations share, so they agree on exactly when an
166	     * owner has been a member for "over a year"; it is {@code false} whenever either date
167	     * is absent.
168	     */
169	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
170	        return registrationDate != null && asOf != null
171	            && ChronoUnit.DAYS.between(registrationDate, asOf) > 365;
172	    }
173	
174	    /**
175	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
176	     * is present, otherwise {@code "PHONE"}.
177	     *
178	     * @return {@code "EMAIL"} or {@code "PHONE"}
179	     */
180	    static String contactPreference(String email) {
181	        if (hasEmail(email)) {
182	            return "EMAIL";
183	        }
184	        return "PHONE";
185	    }
186	
187	    /**
188	     * Whether the owner has an email address on file, i.e. its {@code email} is present
189	     * and not blank. This is the single presence test the email-driven derivations share
190	     * (a membership-level factor and the {@link #contactPreference(String) contact
191	     * preference}), so they agree on exactly what counts as "has an email".
192	     */
193	    private static boolean hasEmail(String email) {
194	        return email != null && !email.isBlank();
195	    }
196	
197	    /**
198	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
199	     * given {@code customerCode}, processed right-to-left with every second digit
200	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
201	     * ignored, and an absent or digit-free customer code yields {@code 0}.
202	     *
203	     * @return the Luhn check digit, from 0 to 9
204	     */
205	    static int checkDigit(String customerCode) {
206	        int sum = 0;
207	        boolean doubleDigit = true;
208	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
209	            char c = customerCode.charAt(i);
210	            if (c < '0' || c > '9') {
211	                continue;
212	            }
213	            int d = c - '0';
214	            if (doubleDigit) {
215	                d *= 2;
216	                if (d > 9) {
217	                    d -= 9;
218	                }
219	            }
220	            sum += d;
221	            doubleDigit = !doubleDigit;
222	        }
223	        return (10 - (sum % 10)) % 10;
224	    }
225	
226	    /**
227	     * The owner's age band, derived from its {@code birthDate} measured against its
228	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
229	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
230	     * over. The age is the number of whole years between the two dates. Returns
231	     * {@code null} when either date is absent, so no band is reported for an owner
232	     * without a supplied birth date.
233	     *
234	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
235	     */
236	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
237	        if (birthDate == null || registrationDate == null) {
238	            return null;
239	        }
240	        int age = Period.between(birthDate, registrationDate).getYears();
241	        if (age < 18) {
242	            return "MINOR";
243	        }
244	        if (age < 65) {
245	            return "ADULT";
246	        }
247	        return "SENIOR";
248	    }
249	
250	    /**
251	     * The single derived key used for duplicate detection, formed as
252	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
253	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
254	     * is the stored (lower-cased) email or the empty string when absent, and the
255	     * household component is the stored {@code householdId} or the empty string
256	     * when the owner belongs to no household.
257	     *
258	     * @return the owner's identity key
259	     */
260	    static String identityKey(String telephone, String email, String householdId) {
261	        String tel = telephone == null ? "" : telephone;
262	        String mail = email == null ? "" : email;
263	        String household = householdId == null ? "" : householdId;
264	        return tel + "|" + mail + "|" + household;
265	    }
266	
267	    /**
268	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
269	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
270	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
271	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
272	     *
273	     * @return the customer code
274	     */
275	    static String customerCode(String region, String telephone, String lastName) {
276	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
277	        return String.format("%s-%s", region, hash8);
278	    }
279	
280	    /**
281	     * The stable identifier for the household an owner belongs to, derived
282	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
283	     * every owner sharing a last name and postcode resolves to the same value. It is the
284	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
285	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
286	     * empty string).
287	     *
288	     * @return the household identifier
289	     */
290	    static String householdId(String normalizedLastName, String postcode) {
291	        String pc = postcode == null ? "" : postcode;
292	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
293	    }
294	
295	    /**
296	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
297	     * hexadecimal string. Callers take the prefix and case they need.
298	     */
299	    static String sha256Hex(String value) {
300	        try {
301	            byte[] digest = MessageDigest.getInstance("SHA-256")
302	                .digest(value.getBytes(StandardCharsets.UTF_8));
303	            StringBuilder hex = new StringBuilder(digest.length * 2);
304	            for (byte b : digest) {
305	                hex.append(String.format("%02x", b));
306	            }
307	            return hex.toString();
308	        } catch (NoSuchAlgorithmException e) {
309	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
310	        }
311	    }
312	}
