340	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
341	    }
342	
343	    /**
344	     * Compute the stable household identifier for this owner, derived deterministically
345	     * from its last name and postcode so every owner sharing a last name and postcode
346	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
347	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
348	     *
349	     * @return the household identifier
350	     */
351	    public String computeHouseholdId() {
352	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
353	    }
354	
355	    /**
356	     * Whether this owner belongs to the same household as {@code other}: that is, they
357	     * share the same last name and postcode. The last name is compared
358	     * case-insensitively with runs of whitespace collapsed to a single space (and
359	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
360	     * absent postcodes count as equal). Owners in the same household resolve to the same
361	     * {@link #computeHouseholdId() household identifier}.
362	     *
363	     * @param other the owner to compare against
364	     * @return {@code true} if both owners share a household
365	     */
366	    public boolean sameHouseholdAs(Owner other) {
367	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
368	            && Objects.equals(this.postcode, other.postcode);
369	    }
370	
371	    /**
372	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
373	     * trim, collapse internal runs of whitespace to a single space and lower-case.
374	     */
375	    private static String normalize(String value) {
376	        if (value == null) {
377	            return "";
378	        }
379	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
380	    }
381	
382	    /**
383	     * Reduce an address to its canonical stored form: trim and collapse runs of
384	     * whitespace to a single space, upper-case, and expand common abbreviations
385	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
386	     * they appear as whole words. The result is what is stored, returned and used
387	     * for every household comparison; it is idempotent, so re-normalising an
388	     * already-normalised address leaves it unchanged.
389	     *
390	     * @param value the raw address (may be {@code null})
391	     * @return the normalised address, or the empty string if {@code value} is
392	     *         {@code null} or blank
393	     */
394	    public static String normalizeAddress(String value) {
395	        if (value == null) {
396	            return "";
397	        }
398	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
399	        if (collapsed.isEmpty()) {
400	            return "";
401	        }
402	        String[] tokens = collapsed.split(" ");
403	        for (int i = 0; i < tokens.length; i++) {
404	            tokens[i] = switch (tokens[i]) {
405	                case "ST" -> "STREET";
406	                case "RD" -> "ROAD";
407	                case "AVE" -> "AVENUE";
408	                default -> tokens[i];
409	            };
410	        }
411	        return String.join(" ", tokens);
412	    }
413	
414	    protected Set<Pet> getPetsInternal() {
415	        if (this.pets == null) {
416	            this.pets = new HashSet<>();
417	        }
418	        return this.pets;
419	    }
420	
421	    protected void setPetsInternal(Set<Pet> pets) {
422	        this.pets = pets;
423	    }
