480	            .count();
481	        return count >= 100;
482	    }
483	
484	    /**
485	     * Determine whether more than 80 owners have already been created for the given
486	     * registration date, i.e. strictly more than 80 existing owners carry that date.
487	     * Evaluated before the new owner is saved, so it reflects only owners that
